1	namespace Meridian.Domain.Jobs;
2	
3	/// <summary>An append-only history row for a job (AD-5). Never updated or deleted.</summary>
4	public sealed class JobEvent
5	{
6	    public const string SystemActor = "system";
7	
8	    /// <summary>Length of the stored actor column.</summary>
9	    public const int MaxActorLength = 64;
10	
11	    private JobEvent()
12	    {
13	        Actor = string.Empty;
14	        PayloadJson = "{}";
15	    }
16	
17	    internal JobEvent(Guid jobId, EventType type, DateTime occurredAtUtc, string actor, string payloadJson)
18	    {
19	        Guards.RequireUtc(occurredAtUtc, nameof(occurredAtUtc));
20	        Id = Guid.NewGuid();
21	        JobId = jobId;
22	        Type = type;
23	        OccurredAtUtc = occurredAtUtc;
24	        Actor = actor;
25	        PayloadJson = payloadJson;
26	    }
27	
28	    public Guid Id { get; private set; }
29	
30	    public Guid JobId { get; private set; }
31	
32	    public EventType Type { get; private set; }
33	
34	    public DateTime OccurredAtUtc { get; private set; }
35	
36	    public string Actor { get; private set; }
37	
38	    public string PayloadJson { get; private set; }
39	}
40	using System.Text.Json;
41	using Meridian.Domain.Contractors;
42	using Meridian.Domain.Messages;
43	using Meridian.Domain.Rules;
44	
45	namespace Meridian.Domain.Jobs;
46	
47	/// <summary>
48	/// One unit of maintenance work. State changes only through methods on this class,
49	/// and every change appends a <see cref="JobEvent"/> (AD-5).
50	/// </summary>
51	public sealed class Job
52	{
53	    private readonly List<Message> _messages = new();
54	    private readonly List<JobEvent> _events = new();
55	
56	    /// <summary>Fired rule ids, comma-separated, in the order they first fired; stored as the <c>RuleIds</c> column.</summary>
57	    private string _ruleIds = string.Empty;
58	
59	    private Job()
60	    {
61	        Reference = string.Empty;
62	    }
63	
64	    public Guid Id { get; private set; }
65	
66	    public string Reference { get; private set; }
67	
68	    public JobStatus Status { get; private set; }
69	
70	    public Urgency Urgency { get; private set; }
71	
72	    public Category Category { get; private set; }
73	
74	    /// <summary>The property the job is at, once <c>PropertyResolver</c> matched one (AD-13); null when unresolved.</summary>
75	    public Guid? PropertyId { get; private set; }
76	
77	    /// <summary>The contractor <c>ContractorLookup</c> suggested for the job's category and building; null means "needs a person".</summary>
78	    public Guid? SuggestedContractorId { get; private set; }
79	
80	    /// <summary>Whether <see cref="SuggestedContractorId"/> is the building's usual contractor or the company default; null without a suggestion.</summary>
81	    public ContractorRule? SuggestedContractorRule { get; private set; }
82	
83	    /// <summary>When the job's first message was received (UTC).</summary>
84	    public DateTime ReceivedAtUtc { get; private set; }
85	
86	    /// <summary>When the job was opened (UTC).</summary>
87	    public DateTime CreatedAtUtc { get; private set; }
88	
89	    /// <summary>Why the job was prepared this way, from the model's proposal (R7). Null until prepared.</summary>
90	    public string? Explanation { get; private set; }
91	
92	    /// <summary>English summary of the issue, from the model's proposal. Null until prepared.</summary>
93	    public string? SummaryEn { get; private set; }
94	
95	    /// <summary>Language of the tenant's message as reported by the model (e.g. <c>pl</c>). Null until prepared.</summary>
96	    public string? Language { get; private set; }
97	
98	    /// <summary>Ids of the emergency rules that fired on this job's messages (see <see cref="EmergencyRuleIds"/>), for the job view.</summary>
99	    public IReadOnlyList<string> RuleIds =>
100	        _ruleIds.Length == 0 ? Array.Empty<string>() : _ruleIds.Split(RuleIdSeparator);
101	
102	    /// <summary>The job's messages: the first plus any follow-ups. A message may also belong to other jobs.</summary>
103	    public IReadOnlyList<Message> Messages => _messages;
104	
105	    /// <summary>Messages attached after the first one (R8).</summary>
106	    public int FollowUpCount => Math.Max(0, _messages.Count - 1);
107	
108	    /// <summary>True while the job can still take follow-ups: not <see cref="JobStatus.Attended"/> or <see cref="JobStatus.Rejected"/>.</summary>
109	    public bool IsOpen => Status is not (JobStatus.Attended or JobStatus.Rejected);
110	
111	    public IReadOnlyList<JobEvent> Events => _events;
112	
113	    /// <summary>
114	    /// Creates a job for one issue of a received message (or the message as a whole when there is no usable issue):
115	    /// status Prepared, category Unsure, urgency Routine. Appends <see cref="EventType.MessageReceived"/> then
116	    /// <see cref="EventType.JobPrepared"/>. A message can start several jobs.
117	    /// </summary>
118	    /// <param name="message">The received message; it becomes the job's first message.</param>
119	    /// <param name="reference">The job reference, e.g. <c>MER-000001</c>.</param>
120	    /// <param name="nowUtc">The current time from the application's clock port (AD-9).</param>
121	    /// <param name="propertyId">The resolved property, or null when it is unresolved (AD-13).</param>
122	    public static Job CreateFromMessage(Message message, string reference, DateTime nowUtc, Guid? propertyId = null)
123	    {
124	        ArgumentNullException.ThrowIfNull(message);
125	        if (string.IsNullOrWhiteSpace(reference) || !reference.StartsWith(JobReference.Prefix, StringComparison.Ordinal))
126	        {
127	            throw new ArgumentException("Reference must start with " + JobReference.Prefix + ".", nameof(reference));
128	        }
129	
130	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
131	        if (propertyId == Guid.Empty)
132	        {
133	            throw new ArgumentException("Property id must not be empty; pass null when unresolved.", nameof(propertyId));
134	        }
135	
136	        var job = new Job
137	        {
138	            Id = Guid.NewGuid(),
139	            Reference = reference,
140	            Status = JobStatus.Prepared,
141	            Urgency = Urgency.Routine,
142	            Category = Category.Unsure,
143	            ReceivedAtUtc = message.ReceivedAtUtc,
144	            CreatedAtUtc = nowUtc,
145	            PropertyId = propertyId,
146	        };
147	
148	        job._messages.Add(message);
149	
150	        job.Append(
151	            EventType.MessageReceived,
152	            message.ReceivedAtUtc,
153	            JobEvent.SystemActor,
154	            new { messageId = message.Id });
155	
156	        job.Append(
157	            EventType.JobPrepared,
158	            nowUtc,
159	            JobEvent.SystemActor,
160	            new
161	            {
162	                reference = job.Reference,
163	                status = job.Status.ToString(),
164	                urgency = job.Urgency.ToString(),
165	                category = job.Category.ToString(),
166	                propertyId = job.PropertyId,
167	            });
168	
169	        return job;
170	    }
171	
172	    /// <summary>
173	    /// Attaches a later message to this open job as a follow-up (R8, AD-13): links the message, appends
174	    /// <see cref="EventType.FollowUpAttached"/> with the message id and this job's reference, then raises urgency to
175	    /// <paramref name="proposal"/> through <see cref="RaiseUrgency"/> (never lowers it, AD-4).
176	    /// </summary>
177	    /// <param name="proposal">The urgency proposed for the follow-up's issue.</param>
178	    public void AttachFollowUp(Message message, Urgency proposal, DateTime nowUtc)
179	    {
180	        ArgumentNullException.ThrowIfNull(message);
181	        if (!Enum.IsDefined(proposal))
182	        {
183	            throw new ArgumentOutOfRangeException(nameof(proposal), proposal, "Unknown urgency.");
184	        }
185	
186	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
187	        if (!IsOpen)
188	        {
189	            throw new InvalidOperationException($"Job {Reference} is {Status} and cannot take follow-ups.");
190	        }
191	
192	        if (_messages.Any(m => m.Id == message.Id))
193	        {
194	            throw new InvalidOperationException("The message is already on this job.");
195	        }
196	
197	        _messages.Add(message);
198	        Append(
199	            EventType.FollowUpAttached,
200	            nowUtc,
201	            JobEvent.SystemActor,
202	            new { messageId = message.Id, reference = Reference, proposedUrgency = proposal.ToString() });
203	        RaiseUrgency(proposal, FollowUpReason, nowUtc);
204	    }
205	
206	    /// <summary>Explanation shown on a job whose message the model found no maintenance problem in.</summary>
207	    public const string NotMaintenanceExplanation =
208	        "The AI found no maintenance problem in this message. A person should check it.";
209	
210	    /// <summary>True once a <see cref="EventType.ModelPrepared"/> or <see cref="EventType.ModelPreparationFailed"/> event exists.</summary>
211	    public bool HasModelOutcome =>
212	        _events.Any(e => e.Type is EventType.ModelPrepared or EventType.ModelPreparationFailed);
213	
214	    /// <summary>
215	    /// Applies a validated model proposal: sets category, explanation, English summary and language, appends
216	    /// <see cref="EventType.ModelPrepared"/> with <paramref name="payloadJson"/>, then raises urgency to the
217	    /// proposal (never lowers it, AD-4).
218	    /// </summary>
219	    /// <param name="payloadJson">Event payload with the model metadata (model id, prompt version, latency, raw output, attempts).</param>
220	    public void ApplyModelPreparation(
221	        Category category,
222	        Urgency urgency,
223	        string explanation,
224	        string summaryEn,
225	        string language,
226	        string payloadJson,
227	        DateTime nowUtc)
228	    {
229	        RequireNoModelOutcome();
230	        if (string.IsNullOrWhiteSpace(explanation))
231	        {
232	            throw new ArgumentException("Explanation is required.", nameof(explanation));
233	        }
234	
235	        if (string.IsNullOrWhiteSpace(summaryEn))
236	        {
237	            throw new ArgumentException("English summary is required.", nameof(summaryEn));
238	        }
239	
240	        if (string.IsNullOrWhiteSpace(language))
241	        {
242	            throw new ArgumentException("Language is required.", nameof(language));
243	        }
244	
245	        RequireJsonObject(payloadJson, nameof(payloadJson));
246	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
247	
248	        Category = category;
249	        Explanation = explanation;
250	        SummaryEn = summaryEn;
251	        Language = language;
252	        AppendRaw(EventType.ModelPrepared, nowUtc, JobEvent.SystemActor, payloadJson);
253	        RaiseUrgency(urgency, "model", nowUtc);
254	    }
255	
256	    /// <summary>
257	    /// Records a valid model answer with no issues (not maintenance): the job keeps category Unsure and its urgency,
258	    /// is flagged for a person with <see cref="NotMaintenanceExplanation"/>, and gets <see cref="EventType.ModelPrepared"/>.
259	    /// </summary>
260	    public void ApplyNotMaintenance(string language, string payloadJson, DateTime nowUtc)
261	    {
262	        RequireNoModelOutcome();
263	        if (string.IsNullOrWhiteSpace(language))
264	        {
265	            throw new ArgumentException("Language is required.", nameof(language));
266	        }
267	
268	        RequireJsonObject(payloadJson, nameof(payloadJson));
269	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
270	        Category = Category.Unsure;
271	        Language = language;
272	        Explanation = NotMaintenanceExplanation;
273	        AppendRaw(EventType.ModelPrepared, nowUtc, JobEvent.SystemActor, payloadJson);
274	    }
275	
276	    /// <summary>
277	    /// Records that the model gave no usable proposal. The job keeps category Unsure and its urgency (RULE-11).
278	    /// </summary>
279	    /// <param name="payloadJson">Event payload with the failure reason, model metadata and validation errors.</param>
280	    public void RecordModelFailure(string payloadJson, DateTime nowUtc)
281	    {
282	        RequireNoModelOutcome();
283	        RequireJsonObject(payloadJson, nameof(payloadJson));
284	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
285	        AppendRaw(EventType.ModelPreparationFailed, nowUtc, JobEvent.SystemActor, payloadJson);
286	    }
287	
288	    /// <summary>
289	    /// Records the emergency rules' result for a message (R4): appends <see cref="EventType.RulesApplied"/> listing
290	    /// each rule id and matched phrase (an empty list when none fired), remembers the fired rule ids, and raises the
291	    /// job to Emergency with reason <c>rule:&lt;id&gt;</c> of the first hit. Never lowers urgency (AD-4).
292	    /// </summary>
293	    /// <param name="hits">The result of <see cref="EmergencyRules.Evaluate"/>.</param>
294	    public void ApplyRules(IReadOnlyList<RuleHit> hits, DateTime nowUtc)
295	    {
296	        ArgumentNullException.ThrowIfNull(hits);
297	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
298	        foreach (var hit in hits)
299	        {
300	            if (hit is null || !EmergencyRuleIds.All.Contains(hit.RuleId))
301	            {
302	                throw new ArgumentException("Unknown emergency rule.", nameof(hits));
303	            }
304	        }
305	
306	        Append(
307	            EventType.RulesApplied,
308	            nowUtc,
309	            JobEvent.SystemActor,
310	            new { rules = hits.Select(h => new { id = h.RuleId, matchedPhrase = h.MatchedPhrase }) });
311	
312	        if (hits.Count == 0)
313	        {
314	            return;
315	        }
316	
317	        var ruleIds = RuleIds.Concat(hits.Select(h => h.RuleId)).Distinct(StringComparer.Ordinal);
318	        _ruleIds = string.Join(RuleIdSeparator, ruleIds);
319	        RaiseUrgency(Urgency.Emergency, RuleReasonPrefix + hits[0].RuleId, nowUtc);
320	    }
321	
322	    /// <summary>
323	    /// Records that a tenant acknowledgement was written to the outbox (R16, AD-8): appends
324	    /// <see cref="EventType.AcknowledgementSent"/> with the template id and the outbound message id.
325	    /// </summary>
326	    /// <param name="outboundId">The id of the stored outbound message.</param>
327	    /// <param name="templateId">The fixed template it was rendered from, e.g. <c>acknowledgement</c> or <c>gas-safety</c>.</param>
328	    public void RecordAcknowledgement(Guid outboundId, string templateId, DateTime nowUtc)
329	    {
330	        if (outboundId == Guid.Empty)
331	        {
332	            throw new ArgumentException("An outbound message id is required.", nameof(outboundId));
333	        }
334	
335	        if (string.IsNullOrWhiteSpace(templateId))
336	        {
337	            throw new ArgumentException("A template id is required.", nameof(templateId));
338	        }
339	
340	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
341	        Append(
342	            EventType.AcknowledgementSent,
343	            nowUtc,
344	            JobEvent.SystemActor,
345	            new { templateId, outboundId });
346	    }
347	
348	    /// <summary>
349	    /// Records the contractor fixed code suggests for the job (R12, AD-3), when the job is created or its category
350	    /// changes: sets <see cref="SuggestedContractorId"/> and <see cref="SuggestedContractorRule"/> and appends
351	    /// <see cref="EventType.ContractorSuggested"/> with the contractor id and rule (<c>building</c> or <c>default</c>).
352	    /// The same suggestion again changes nothing and writes no event. An Unsure job gets no suggestion.
353	    /// </summary>
354	    /// <returns>True when the suggestion changed.</returns>
355	    public bool SuggestContractor(ContractorSuggestion suggestion, DateTime nowUtc)
356	    {
357	        ArgumentNullException.ThrowIfNull(suggestion);
358	        if (suggestion.ContractorId == Guid.Empty)
359	        {
360	            throw new ArgumentException("A contractor id is required.", nameof(suggestion));
361	        }
362	
363	        if (!Enum.IsDefined(suggestion.Rule))
364	        {
365	            throw new ArgumentOutOfRangeException(nameof(suggestion), suggestion.Rule, "Unknown contractor rule.");
366	        }
367	
368	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
369	        if (Category == Category.Unsure)
370	        {
371	            throw new InvalidOperationException($"Job {Reference} is Unsure and needs a person, not a suggested contractor.");
372	        }
373	
374	        if (SuggestedContractorId == suggestion.ContractorId && SuggestedContractorRule == suggestion.Rule)
375	        {
376	            return false;
377	        }
378	
379	        SuggestedContractorId = suggestion.ContractorId;
380	        SuggestedContractorRule = suggestion.Rule;
381	        Append(
382	            EventType.ContractorSuggested,
383	            nowUtc,
384	            JobEvent.SystemActor,
385	            new { contractorId = suggestion.ContractorId, rule = suggestion.Rule.ToString().ToLowerInvariant() });
386	        return true;
387	    }
388	
389	    /// <summary>
390	    /// The only way urgency goes down (AD-4): a person sets the urgency to <paramref name="level"/>, higher or lower,
391	    /// and <see cref="EventType.UrgencySetByPerson"/> records who, from what, to what and why. Called from the review
392	    /// use case only.
393	    /// </summary>
394	    /// <param name="actor">The acting person (e.g. Rachel); never the system actor.</param>
395	    /// <param name="reason">Why the person changed it; required.</param>
396	    public void SetUrgencyByPerson(Urgency level, string actor, string reason, DateTime nowUtc)
397	    {
398	        if (!Enum.IsDefined(level))
399	        {
400	            throw new ArgumentOutOfRangeException(nameof(level), level, "Unknown urgency.");
401	        }
402	
403	        if (string.IsNullOrWhiteSpace(actor) || string.Equals(actor.Trim(), JobEvent.SystemActor, StringComparison.OrdinalIgnoreCase))
404	        {
405	            throw new ArgumentException("A person is required.", nameof(actor));
406	        }
407	
408	        if (actor.Length > JobEvent.MaxActorLength)
409	        {
410	            throw new ArgumentException($"Actor must be at most {JobEvent.MaxActorLength} characters.", nameof(actor));
411	        }
412	
413	        if (string.IsNullOrWhiteSpace(reason))
414	        {
415	            throw new ArgumentException("A reason is required.", nameof(reason));
416	        }
417	
418	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
419	        var from = Urgency;
420	        Urgency = level;
421	        Append(
422	            EventType.UrgencySetByPerson,
423	            nowUtc,
424	            actor,
425	            new { from = from.ToString(), to = level.ToString(), reason });
426	    }
427	
428	    /// <summary>
429	    /// The only automatic urgency change (AD-4): raises to <paramref name="level"/> and appends
430	    /// <see cref="EventType.UrgencyRaised"/>; a value lower than or equal to the current urgency is ignored.
431	    /// </summary>
432	    /// <returns>True when the urgency changed.</returns>
433	    public bool RaiseUrgency(Urgency level, string reason, DateTime nowUtc)
434	    {
435	        if (!Enum.IsDefined(level))
436	        {
437	            throw new ArgumentOutOfRangeException(nameof(level), level, "Unknown urgency.");
438	        }
439	
440	        if (string.IsNullOrWhiteSpace(reason))
441	        {
442	            throw new ArgumentException("A reason is required.", nameof(reason));
443	        }
444	
445	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
446	        if (level <= Urgency)
447	        {
448	            return false;
449	        }
450	
451	        var from = Urgency;
452	        Urgency = level;
453	        Append(
454	            EventType.UrgencyRaised,
455	            nowUtc,
456	            JobEvent.SystemActor,
457	            new { from = from.ToString(), to = level.ToString(), reason });
458	        return true;
459	    }
460	
461	    /// <summary>What the job still needs before it can be approved (AD-6).</summary>
462	    public static class ApprovalNeeds
463	    {
464	        /// <summary>The category is Unsure: a person must set one.</summary>
465	        public const string Category = "category";
466	
467	        /// <summary>No contractor is suggested or chosen.</summary>
468	        public const string Contractor = "contractor";
469	    }
470	
471	    /// <summary>
472	    /// What stops approval: <see cref="ApprovalNeeds.Category"/> while the category is Unsure and
473	    /// <see cref="ApprovalNeeds.Contractor"/> while there is no contractor. Empty when the job can be approved
474	    /// (status aside).
475	    /// </summary>
476	    public IReadOnlyList<string> MissingForApproval()
477	    {
478	        var missing = new List<string>();
479	        if (Category == Category.Unsure)
480	        {
481	            missing.Add(ApprovalNeeds.Category);
482	        }
483	
484	        if (SuggestedContractorId is null)
485	        {
486	            missing.Add(ApprovalNeeds.Contractor);
487	        }
488	
489	        return missing;
490	    }
491	
492	    /// <summary>
493	    /// A person approves the job (AD-6: Prepared → Approved) and <see cref="EventType.JobApproved"/> records who, with
494	    /// the category, urgency and contractor approved. Never automatic. Nothing is sent to the contractor here.
495	    /// </summary>
496	    /// <exception cref="JobStateException">The job is not Prepared, or still has no category or contractor.</exception>
497	    public void Approve(string actor, DateTime nowUtc)
498	    {
499	        RequirePersonActor(actor);
500	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
501	        RequirePrepared("approved");
502	        var missing = MissingForApproval();
503	        if (missing.Count > 0)
504	        {
505	            throw new JobStateException(
506	                $"Job {Reference} cannot be approved yet: it needs a {string.Join(" and a ", missing)}.", Status, missing);
507	        }
508	
509	        var from = Status;
510	        Status = JobStatus.Approved;
511	        Append(
512	            EventType.JobApproved,
513	            nowUtc,
514	            actor,
515	            new
516	            {
517	                from = from.ToString(),
518	                to = Status.ToString(),
519	                category = Category.ToString(),
520	                urgency = Urgency.ToString(),
521	                contractorId = SuggestedContractorId,
522	                contractorRule = SuggestedContractorRule?.ToString().ToLowerInvariant(),
523	            });
524	    }
525	
526	    /// <summary>
527	    /// A person rejects the job with a reason (AD-6: Prepared → Rejected); <see cref="EventType.JobRejected"/> records
528	    /// who and why. A rejected job takes no more follow-ups.
529	    /// </summary>
530	    /// <exception cref="JobStateException">The job is not Prepared.</exception>
531	    public void Reject(string actor, string reason, DateTime nowUtc)
532	    {
533	        RequirePersonActor(actor);
534	        if (string.IsNullOrWhiteSpace(reason))
535	        {
536	            throw new ArgumentException("A reason is required.", nameof(reason));
537	        }
538	
539	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
540	        RequirePrepared("rejected");
541	        var from = Status;
542	        Status = JobStatus.Rejected;
543	        Append(
544	            EventType.JobRejected,
545	            nowUtc,
546	            actor,
547	            new { from = from.ToString(), to = Status.ToString(), reason = reason.Trim() });
548	    }
549	
550	    /// <summary>Field names written in <see cref="EventType.JobEdited"/> payloads.</summary>
551	    public static class EditedFields
552	    {
553	        public const string Category = "category";
554	        public const string Contractor = "contractor";
555	        public const string Property = "property";
556	    }
557	
558	    /// <summary>
559	    /// A person sets the category of a Prepared job; <see cref="EventType.JobEdited"/> records the field, the value
560	    /// before and after. The same value again changes nothing. The caller re-runs the contractor lookup.
561	    /// </summary>
562	    /// <returns>True when the category changed.</returns>
563	    /// <exception cref="JobStateException">The job is not Prepared.</exception>
564	    public bool EditCategory(Category category, string actor, DateTime nowUtc)
565	    {
566	        if (!Enum.IsDefined(category))
567	        {
568	            throw new ArgumentOutOfRangeException(nameof(category), category, "Unknown category.");
569	        }
570	
571	        RequirePersonActor(actor);
572	        Guards.RequireUtc(nowUtc, nameof(nowUtc));
573	        RequirePrepared("edited");
574	        if (category == Category)
575	        {
576	            return false;
577	        }
578	
579	        var before = Category;
580	        Category = category;
581	        AppendEdited(EditedFields.Category, before.ToString(), category.ToString(), actor, nowUtc);
582	        return true;
583	    }
584	
585	    /// <summary>
586	    /// A person sets the property of a Prepared job (for example one the address did not resolve to);
587	    /// <see cref="EventType.JobEdited"/> records the property ids before and after.
588	    /// </summary>
589	    /// <returns>True when the property changed.</returns>
590	    /// <exception cref="JobStateException">The job is not Prepared.</exception>
591	    public bool EditProperty(Guid propertyId, string actor, DateTime nowUtc)
592	    {
593	        if (propertyId == Guid.Empty)
594	        {
595	            throw new ArgumentException("A property id is required.", nameof(propertyId));
596	        }
597	
598	        RequirePersonActor(actor);
