866	{
867	    private readonly IJobRepository _jobs;
868	    private readonly IPropertyRepository _properties;
869	    private readonly IContractorRepository _contractors;
870	
871	    public GetJob(IJobRepository jobs, IPropertyRepository properties, IContractorRepository contractors)
872	    {
873	        _jobs = jobs;
874	        _properties = properties;
875	        _contractors = contractors;
876	    }
