878	    public async Task<JobDetail?> ExecuteAsync(Guid id, CancellationToken cancellationToken)
879	    {
880	        var job = await _jobs.GetAsync(id, cancellationToken);
881	        if (job is null)
882	        {
883	            return null;
884	        }
885	
886	        var properties = (await _properties.ListAsync(cancellationToken)).ToDictionary(p => p.Id);
887	        var contractors = (await _contractors.ListAsync(cancellationToken)).ToDictionary(c => c.Id);
888	        var property = job.PropertyId is { } propertyId ? properties.GetValueOrDefault(propertyId) : null;
889	        var contractor = job.SuggestedContractorId is { } contractorId ? contractors.GetValueOrDefault(contractorId) : null;
890	
891	        string PropertyName(Guid? value) =>
892	            value is not { } key ? "none" : properties.TryGetValue(key, out var p) ? p.Name : key.ToString();
893	
894	        string ContractorName(Guid? value) =>
895	            value is not { } key ? "none" : contractors.TryGetValue(key, out var c) ? c.Name : key.ToString();
896	
897	        var events = job.Events
898	            .OrderBy(e => e.OccurredAtUtc)
899	            .Select(e => new JobDetailEvent(e.Type, e.OccurredAtUtc, e.Actor, Summarise(e, PropertyName, ContractorName)))
900	            .ToList();
901	
902	        return new JobDetail(
903	            job.Id,
904	            job.Reference,
905	            job.Status,
906	            job.Urgency,
907	            job.Category,
908	            job.ReceivedAtUtc,
909	            job.Explanation,
910	            job.SummaryEn,
911	            job.Language,
912	            job.PropertyId,
913	            property?.Name,
914	            property?.Building?.Name,
915	            contractor is null
916	                ? null
917	                : new JobDetailContractor(contractor.Id, contractor.Name, contractor.Phone, contractor.Trade, job.SuggestedContractorRule),
918	            RulesOf(job),
919	            job.Messages
920	                .OrderBy(m => m.ReceivedAtUtc)
921	                .Select(m => new JobDetailMessage(m.Id, m.Sender, m.Text, m.ReceivedAtUtc))
922	                .ToList(),
923	            events,
924	            job.Status == JobStatus.Prepared,
925	            job.MissingForApproval());
