928	    private static IReadOnlyList<JobDetailRule> RulesOf(Job job)
929	    {
930	        var rules = new List<JobDetailRule>();
931	        foreach (var applied in job.Events.Where(e => e.Type == EventType.RulesApplied).OrderBy(e => e.OccurredAtUtc))
932	        {
933	            using var payload = JsonDocument.Parse(applied.PayloadJson);
934	            if (!payload.RootElement.TryGetProperty("rules", out var list) || list.ValueKind != JsonValueKind.Array)
935	            {
936	                continue;
937	            }
938	
939	            foreach (var rule in list.EnumerateArray())
940	            {
941	                var id = Text(rule, "id");
942	                if (id is not null && rules.All(r => r.Id != id))
943	                {
944	                    rules.Add(new JobDetailRule(id, Text(rule, "matchedPhrase") ?? string.Empty));
945	                }
946	            }
947	        }
948	
949	        return rules;
950	    }
951	
952	    private static string Summarise(JobEvent e, Func<Guid?, string> propertyName, Func<Guid?, string> contractorName)
953	    {
954	        using var payload = JsonDocument.Parse(e.PayloadJson);
955	        var root = payload.RootElement;
956	        return e.Type switch
957	        {
958	            EventType.MessageReceived => "Message received",
959	            EventType.JobPrepared => $"Job prepared as {Text(root, "category")}, {Text(root, "urgency")}",
960	            EventType.ModelPrepared => "AI prepared the job" + (Text(root, "modelId") is { } model ? $" ({model})" : string.Empty),
961	            EventType.ModelPreparationFailed => "AI gave no usable answer" + (Text(root, "reason") is { } reason ? $" ({reason})" : string.Empty),
962	            EventType.UrgencyRaised => $"Urgency raised {Text(root, "from")} → {Text(root, "to")} ({Text(root, "reason")})",
963	            EventType.UrgencySetByPerson => $"Urgency set {Text(root, "from")} → {Text(root, "to")}: {Text(root, "reason")}",
964	            EventType.RulesApplied => RulesSummary(root),
965	            EventType.FollowUpAttached => "Follow-up message attached",
966	            EventType.AcknowledgementSent => $"Tenant sent {Text(root, "templateId")}",
967	            EventType.ContractorSuggested =>
968	                $"Contractor suggested: {contractorName(GuidOf(root, "contractorId"))} ({Text(root, "rule")})",
969	            EventType.JobApproved => "Approved",
970	            EventType.JobRejected => $"Rejected: {Text(root, "reason")}",
971	            EventType.JobEdited => EditedSummary(root, propertyName, contractorName),
972	            _ => e.Type.ToString(),
973	        };
974	    }
975	
976	    private static string RulesSummary(JsonElement root)
977	    {
978	        var ids = root.TryGetProperty("rules", out var list) && list.ValueKind == JsonValueKind.Array
979	            ? list.EnumerateArray().Select(r => Text(r, "id")).OfType<string>().ToList()
980	            : new List<string>();
981	        return ids.Count == 0 ? "Emergency rules: none fired" : $"Emergency rules fired: {string.Join(", ", ids)}";
982	    }
983	
984	    private static string EditedSummary(JsonElement root, Func<Guid?, string> propertyName, Func<Guid?, string> contractorName)
985	    {
986	        var field = Text(root, "field");
987	        var (before, after) = field switch
988	        {
989	            Job.EditedFields.Contractor => (contractorName(GuidOf(root, "before")), contractorName(GuidOf(root, "after"))),
990	            Job.EditedFields.Property => (propertyName(GuidOf(root, "before")), propertyName(GuidOf(root, "after"))),
991	            _ => (Text(root, "before") ?? "none", Text(root, "after") ?? "none"),
992	        };
993	        var cause = Text(root, "cause") is { } c ? $" (after {c} change)" : string.Empty;
994	        return $"Edited {field}: {before} → {after}{cause}";
995	    }
996	
997	    private static string? Text(JsonElement element, string name) =>
998	        element.ValueKind == JsonValueKind.Object
999	        && element.TryGetProperty(name, out var value)
1000	        && value.ValueKind == JsonValueKind.String
1001	            ? value.GetString()
1002	            : null;
1003	
1004	    private static Guid? GuidOf(JsonElement element, string name) =>
1005	        element.ValueKind == JsonValueKind.Object
1006	        && element.TryGetProperty(name, out var value)
1007	        && value.ValueKind == JsonValueKind.String
1008	        && Guid.TryParse(value.GetString(), out var id)
1009	            ? id
1010	            : null;
1011	}
